import pandas as pd
import numpy as np


TARGET_COLUMN = 'target'


def sigmoid(z):
    return 1.0 / (1.0 + np.exp(-np.clip(z, -500, 500)))


def gini(y):
    if len(y) == 0:
        return 0.0
    p = y.mean()
    return 2 * p * (1 - p)


class DecisionTree:
    def __init__(self, max_depth=3, min_samples_leaf=2, max_features=None, rng=None):
        self.max_depth = max_depth
        self.min_samples_leaf = min_samples_leaf
        self.max_features = max_features
        self.rng = rng or np.random.RandomState(42)
        self.tree = None

    def fit(self, X, y):
        self.tree = self._build(X, y, depth=0)
        return self

    def _build(self, X, y, depth):
        n, d = X.shape
        if depth >= self.max_depth or n < 2 * self.min_samples_leaf or len(np.unique(y)) == 1:
            return {'leaf': True, 'val': y.mean()}

        if self.max_features and self.max_features < d:
            feat_idx = self.rng.choice(d, self.max_features, replace=False)
        else:
            feat_idx = np.arange(d)

        best_gain = -1
        best_feat = None
        best_thr = None
        parent_gini = gini(y)

        for j in feat_idx:
            vals = np.unique(X[:, j])
            if len(vals) < 2:
                continue
            thresholds = (vals[:-1] + vals[1:]) / 2
            # subsample thresholds if too many
            if len(thresholds) > 20:
                idx = self.rng.choice(len(thresholds), 20, replace=False)
                thresholds = thresholds[idx]
            for thr in thresholds:
                left = y[X[:, j] <= thr]
                right = y[X[:, j] > thr]
                if len(left) < self.min_samples_leaf or len(right) < self.min_samples_leaf:
                    continue
                gain = parent_gini - (len(left) * gini(left) + len(right) * gini(right)) / n
                if gain > best_gain:
                    best_gain = gain
                    best_feat = j
                    best_thr = thr

        if best_feat is None:
            return {'leaf': True, 'val': y.mean()}

        mask = X[:, best_feat] <= best_thr
        return {
            'leaf': False,
            'feat': best_feat,
            'thr': best_thr,
            'left': self._build(X[mask], y[mask], depth + 1),
            'right': self._build(X[~mask], y[~mask], depth + 1),
        }

    def predict_proba(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])

    def _predict_one(self, x, node):
        if node['leaf']:
            return node['val']
        if x[node['feat']] <= node['thr']:
            return self._predict_one(x, node['left'])
        return self._predict_one(x, node['right'])


def random_forest_predict(X_train, y_train, X_test, n_trees=200, max_depth=4,
                          min_samples_leaf=2, max_features=None, seed=42):
    rng = np.random.RandomState(seed)
    n = len(X_train)
    if max_features is None:
        max_features = max(1, int(np.sqrt(X_train.shape[1])))

    probs = np.zeros(len(X_test))
    for t in range(n_trees):
        idx = rng.choice(n, n, replace=True)
        tree = DecisionTree(max_depth=max_depth, min_samples_leaf=min_samples_leaf,
                           max_features=max_features, rng=rng)
        tree.fit(X_train[idx], y_train[idx])
        probs += tree.predict_proba(X_test)
    probs /= n_trees
    return probs


def knn_predict(X_train, y_train, X_test, k):
    preds = []
    for i in range(len(X_test)):
        dists = np.sqrt(((X_train - X_test[i]) ** 2).sum(axis=1))
        nn_idx = np.argsort(dists)[:k]
        nn_labels = y_train[nn_idx]
        pred = np.bincount(nn_labels.astype(int)).argmax()
        preds.append(pred)
    return np.array(preds)


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Ensemble of multiple random forests and kNN with feature selection."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
    X_train = train[feature_cols].values.astype(float)
    y_train = train[TARGET_COLUMN].values.astype(float)
    X_test = test[feature_cols].values.astype(float)

    # Standardize
    mu = X_train.mean(axis=0)
    std = X_train.std(axis=0) + 1e-8
    X_train_s = (X_train - mu) / std
    X_test_s = (X_test - mu) / std

    # Feature selection by correlation
    corrs = np.array([np.abs(np.corrcoef(X_train_s[:, j], y_train)[0, 1]) for j in range(X_train_s.shape[1])])

    # Collect predictions from multiple configs
    all_probs = []

    # RF with all features, various depths
    for depth in [3, 4, 5, 6]:
        for msl in [1, 2, 3]:
            probs = random_forest_predict(X_train_s, y_train, X_test_s,
                                          n_trees=200, max_depth=depth,
                                          min_samples_leaf=msl, seed=42 + depth * 10 + msl)
            all_probs.append(probs)

    # RF with top features
    for n_feat in [10, 15, 20, 30]:
        top_idx = np.argsort(corrs)[-n_feat:]
        for depth in [3, 4, 5]:
            mf = max(1, int(np.sqrt(n_feat)))
            probs = random_forest_predict(X_train_s[:, top_idx], y_train, X_test_s[:, top_idx],
                                          n_trees=200, max_depth=depth,
                                          min_samples_leaf=2, max_features=mf, seed=42 + n_feat + depth)
            all_probs.append(probs)

    # kNN with different k and feature sets
    for n_feat in [10, 20, 50]:
        if n_feat < 50:
            top_idx = np.argsort(corrs)[-n_feat:]
            Xtr = X_train_s[:, top_idx]
            Xte = X_test_s[:, top_idx]
        else:
            Xtr = X_train_s
            Xte = X_test_s
        for k in [3, 5, 7, 9, 11]:
            probs = np.zeros(len(X_test))
            for i in range(len(Xte)):
                dists = np.sqrt(((Xtr - Xte[i]) ** 2).sum(axis=1))
                nn_idx = np.argsort(dists)[:k]
                probs[i] = y_train[nn_idx].mean()
            all_probs.append(probs)

    # Average all predictions
    ensemble_probs = np.mean(all_probs, axis=0)
    # Threshold tuning: try slightly adjusted threshold
    # Since class 1 is majority (55%), slight bias toward 1 might help
    preds = (ensemble_probs >= 0.52).astype(int)

    predictions = pd.DataFrame({"prediction": preds})
    predictions.to_csv(output_csv, index=False)

